CREATE TABLE private_files(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN('kyc','deposit','payout')),name text NOT NULL,mime text NOT NULL,encrypted bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE kyc_cases(id uuid PRIMARY KEY,user_id uuid NOT NULL UNIQUE REFERENCES users(id),legal_name text NOT NULL,country text NOT NULL,document_type text NOT NULL,document_ids jsonb NOT NULL,status text NOT NULL CHECK(status IN('pending','approved','rejected','more_information')),reason text NOT NULL DEFAULT '',reviewer_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE crypto_settings(route_id text PRIMARY KEY,address text NOT NULL,memo text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT false,withdrawal_enabled boolean NOT NULL DEFAULT false,confirmations integer NOT NULL CHECK(confirmations>0),min_atoms numeric(78,0) NOT NULL CHECK(min_atoms>0),fee_atoms numeric(78,0) NOT NULL CHECK(fee_atoms>=0),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE money_accounts(user_id uuid NOT NULL REFERENCES users(id),asset text NOT NULL CHECK(asset IN('BTC','ETH','USDC','USDT','XRP','TRX')),available numeric(78,0) NOT NULL DEFAULT 0 CHECK(available>=0),reserved numeric(78,0) NOT NULL DEFAULT 0 CHECK(reserved>=0),PRIMARY KEY(user_id,asset));
CREATE TABLE deposits(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),route_id text NOT NULL REFERENCES crypto_settings(route_id),chain text NOT NULL,asset text NOT NULL,amount_atoms numeric(78,0) NOT NULL CHECK(amount_atoms>0),tx_hash text NOT NULL,transfer_index integer NOT NULL CHECK(transfer_index>=0),proof_id uuid NOT NULL REFERENCES private_files(id),status text NOT NULL CHECK(status IN('pending','approved','rejected')),reason text NOT NULL DEFAULT '',verification jsonb,reviewer_id uuid REFERENCES users(id),idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key),UNIQUE(chain,tx_hash,transfer_index));
CREATE TABLE withdrawals(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),route_id text NOT NULL REFERENCES crypto_settings(route_id),chain text NOT NULL,asset text NOT NULL,amount_atoms numeric(78,0) NOT NULL CHECK(amount_atoms>0),fee_atoms numeric(78,0) NOT NULL CHECK(fee_atoms>=0 AND fee_atoms<amount_atoms),address text NOT NULL,memo text NOT NULL DEFAULT '',status text NOT NULL CHECK(status IN('pending','approved','processing','completed','rejected','cancelled')),reason text NOT NULL DEFAULT '',reviewer_id uuid REFERENCES users(id),tx_hash text,payout_index integer,proof_id uuid REFERENCES private_files(id),verification jsonb,idempotency_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key),UNIQUE(chain,tx_hash,payout_index));
CREATE TABLE money_journals(id uuid PRIMARY KEY,reference text NOT NULL UNIQUE,asset text NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE money_lines(journal_id uuid NOT NULL REFERENCES money_journals(id),account text NOT NULL,amount_atoms numeric(78,0) NOT NULL);
CREATE INDEX private_files_owner_idx ON private_files(user_id);
CREATE INDEX deposits_owner_idx ON deposits(user_id,created_at);
CREATE INDEX withdrawals_owner_idx ON withdrawals(user_id,created_at);

UPDATE demo_snapshots SET snapshot=replace(snapshot::text,'Bank transfer','Crypto · TRC20')::jsonb;
